# test: python 3.13 · numpy 2.5.4
# PC'de çalıştır — gerekli: numpy
# Sıfırdan GBDT (tek özellikli küçük ağaçlar): küçültme, ağaç sayısı, erken durdurma, derinlik.
import numpy as np

rng = np.random.default_rng(0)
f = lambda x: 2 * np.sin(3 * x) + 0.4 * x
xtr = rng.uniform(-2, 2, 1000); ytr = f(xtr) + rng.normal(0, 0.35, 1000)
xte = rng.uniform(-2, 2, 5000); yte = f(xte) + rng.normal(0, 0.35, 5000)
print(f"gürültünün varyansı: {0.35**2:.3f} (bu tabanın altına inemez)")


def agac(x, r, derinlik, min_yaprak=8):
    """1 boyutlu regresyon ağacı; yaprak değeri = artık ortalaması."""
    if derinlik == 0 or len(x) < 2 * min_yaprak:
        return float(r.mean())
    en_iyi = (np.inf, None)
    for e in np.quantile(x, np.linspace(0.1, 0.9, 12)):
        sol = x <= e
        if sol.sum() < min_yaprak or (~sol).sum() < min_yaprak:
            continue
        sse = ((r[sol] - r[sol].mean()) ** 2).sum() + ((r[~sol] - r[~sol].mean()) ** 2).sum()
        if sse < en_iyi[0]:
            en_iyi = (sse, e)
    if en_iyi[1] is None:
        return float(r.mean())
    e = en_iyi[1]; sol = x <= e
    return (e, agac(x[sol], r[sol], derinlik - 1, min_yaprak), agac(x[~sol], r[~sol], derinlik - 1, min_yaprak))


def tahmin(a, x):
    if not isinstance(a, tuple):
        return np.full(len(x), a)
    e, L, R = a
    out = np.empty(len(x)); sol = x <= e
    out[sol] = tahmin(L, x[sol]); out[~sol] = tahmin(R, x[~sol])
    return out


def gbdt(lr, M, derinlik=4, sabir=None):
    F, Fv = np.full(len(ytr), ytr.mean()), np.full(len(yte), ytr.mean())
    gecmis, en_iyi, en_iyi_M = [], np.inf, 0
    for m in range(1, M + 1):
        a = agac(xtr, ytr - F, derinlik)
        F += lr * tahmin(a, xtr); Fv += lr * tahmin(a, xte)
        hata = np.mean((yte - Fv) ** 2); gecmis.append(hata)
        if hata < en_iyi:
            en_iyi, en_iyi_M = hata, m
        if sabir is not None and m - en_iyi_M >= sabir:
            break
    return F, Fv, gecmis, en_iyi_M


print(f"\n{'lr':>6} {'M':>5} {'lr*M':>6} {'eğitim MSE':>11} {'test MSE':>9}")
for lr, M in [(1.0, 50), (0.3, 167), (0.1, 500), (0.03, 1667), (0.01, 5000)]:
    F, Fv, _, _ = gbdt(lr, M)
    print(f"{lr:6.2f} {M:5d} {lr*M:6.1f} {np.mean((ytr-F)**2):11.4f} {np.mean((yte-Fv)**2):9.4f}")

print("\nerken durdurma (lr=0.1, azami 3000 adım, sabır 40):")
F, Fv, gecmis, en_iyi_M = gbdt(0.1, 3000, sabir=40)
for m in sorted({1, 10, 50, en_iyi_M, min(en_iyi_M + 20, len(gecmis)), len(gecmis)}):
    print(f"  adım {m:5d}: doğrulama MSE {gecmis[m-1]:.4f}")
print(f"  durdu: {len(gecmis)} adım | en iyi adım {en_iyi_M} (MSE {gecmis[en_iyi_M-1]:.4f}) | "
      f"son MSE {gecmis[-1]:.4f} | aşırı öğrenme kaybı {gecmis[-1]-gecmis[en_iyi_M-1]:+.4f}")

F6, Fv6, g6, best6 = gbdt(0.05, 3000, derinlik=6, sabir=60)
print(f"\nderinlik 6 + lr=0.05: durdu {len(g6)} adım | en iyi {best6} (MSE {g6[best6-1]:.4f}) | "
      f"son {g6[-1]:.4f} | erken durdurma kazancı {g6[-1]-g6[best6-1]:+.4f}")

print("\nderinlik etkisi (lr=0.1, M=300):")
for d in (1, 2, 4, 6):
    F, Fv, _, _ = gbdt(0.1, 300, derinlik=d)
    print(f"  derinlik {d}: eğitim {np.mean((ytr-F)**2):.4f} test {np.mean((yte-Fv)**2):.4f}")
```

Şimdi iskelet: bütçe, yeniden deneme, tipli devir teslim ve iz kaydı. Sahte model, kontrol akışını görünür kılmak için; muhasebe gerçek.

```python
# PC'de çalıştır — gerekli: yok (standart kütüphane)
# Üretim iskeleti: bütçe, yeniden deneme, devir teslim sözleşmesi, iz kaydı.
# Model yerine tohumlanmış sahte bir LLM var; kontrol akışı ve maliyet muhasebesi gerçek.
import random, time
from contextlib import contextmanager

class ButceAsildi(Exception):
    pass

class GeciciHata(Exception):
    pass

class Butce:
    def __init__(self, azami_cagri=10, azami_token=4000):
        self.azami_cagri, self.azami_token = azami_cagri, azami_token
        self.cagri = self.token = 0
    def harca(self, token):
        self.cagri += 1; self.token += token
        if self.cagri > self.azami_cagri or self.token > self.azami_token:
            raise ButceAsildi(f"cagri={self.cagri} token={self.token}")

class SahteLLM:
    """Rol başına hata olasılığı ve token maliyeti olan deterministik sahte model."""
    def __init__(self, seed=0):
        self.rng = random.Random(seed)
        self.p = {"arastirmaci": 0.92, "yazici": 0.90, "dogrulayici": 0.95}
    def cagir(self, rol, metin, butce):
        butce.harca(len(metin)//4 + 120)
        if self.rng.random() > self.p[rol]:
            raise GeciciHata(rol)
        return {"arastirmaci": {"notlar": ["kaynak-1", "kaynak-2"]},
                "yazici": {"taslak": "cevap:" + str(len(metin))},
                "dogrulayici": {"gecti": self.rng.random() < 0.9}}[rol]

IZLER = []
@contextmanager
def iz(ad, ebeveyn=None):
    kayit = {"ad": ad, "ebeveyn": ebeveyn, "bas": time.perf_counter()}
    try:
        yield kayit
    finally:
        kayit["sure"] = time.perf_counter() - kayit["bas"]
        IZLER.append(kayit)

def dene(fn, deneme=2):
    for i in range(deneme):
        try:
            return fn()
        except GeciciHata:
            if i == deneme - 1:
                raise

def arastirmaci(llm, durum, butce, ebeveyn):
    with iz("arastirmaci", ebeveyn):
        durum.update(dene(lambda: llm.cagir("arastirmaci", durum["gorev"], butce)))
    return durum

def yazici(llm, durum, butce, ebeveyn):
    if "notlar" not in durum:                     # devir teslim sözleşmesi: eksik alan
        raise KeyError("notlar yok")
    with iz("yazici", ebeveyn):
        durum.update(dene(lambda: llm.cagir("yazici", str(durum["notlar"]), butce)))
    return durum

def dogrulayici(llm, durum, butce, ebeveyn):
    with iz("dogrulayici", ebeveyn):
        sonuc = dene(lambda: llm.cagir("dogrulayici", durum["taslak"], butce))
    return sonuc["gecti"]

def gorev_calistir(llm, gorev, butce):
    with iz("supervisor"):
        durum = {"gorev": gorev}
        try:
            arastirmaci(llm, durum, butce, "supervisor")
            for deneme in range(2):               # doğrulayıcı reddederse bir kez daha yaz
                yazici(llm, durum, butce, "supervisor")
                if dogrulayici(llm, durum, butce, "supervisor"):
                    return True, butce
            return False, butce
        except GeciciHata:
            return False, butce

llm = SahteLLM(seed=7)
basari = cagri = token = N = 0
for _ in range(1000):
    N += 1
    try:
        ok, b = gorev_calistir(llm, "Uzun bir belgeyi özetle", Butce())
        basari += ok; cagri += b.cagri; token += b.token
    except ButceAsildi:
        pass
print(f"gorev {N} | basari {basari/N:.3f} | cagri/gorev {cagri/N:.2f} "
      f"| token/gorev {token/N:.0f}")

# dar bütçe: 2 çağrıdan sonra görev yarıda kalır
basari2 = durdurma2 = 0
for _ in range(200):
    try:
        ok, _ = gorev_calistir(SahteLLM(seed=3), "dar butce", Butce(azami_cagri=2))
        basari2 += ok
    except ButceAsildi:
        durdurma2 += 1
print(f"dar butce: basari {basari2/200:.3f} | durdurma {durdurma2}/200")

# devir teslim sözleşmesi: alan eksikse araç çalışmaz
try:
    yazici(SahteLLM(seed=1), {"gorev": "x"}, Butce(), None)
except KeyError as e:
    print("devir teslim hatasi:", e)

IZLER.clear()
gorev_calistir(SahteLLM(seed=1), "kısa gorev", Butce())
for k in IZLER:
    print(f"iz: {k['ad']:14s} {k['sure']*1000:6.2f} ms  ebeveyn={k['ebeveyn']}")

# Beklenen çıktı:
# gorev 1000 | basari 0.967 | cagri/gorev 3.41 | token/gorev 424
# dar butce: basari 0.000 | durdurma 200/200
# devir teslim hatasi: 'notlar yok'
# iz: arastirmaci      0.00 ms  ebeveyn=supervisor
# iz: yazici           0.00 ms  ebeveyn=supervisor
# iz: dogrulayici      0.00 ms  ebeveyn=supervisor
# iz: supervisor       0.01 ms  ebeveyn=None
```

Dar bütçede başarı 0: ilk çağrılar bütçeyi tüketiyor, görev yarıda kalıyor. Bu, üretimde "kota doldu" hatasının prototipidir. İz kaydı, hangi adımın ne kadar sürdüğünü ve kimin altında çalıştığını gösterir — bir sonraki dersin temeli.

# Pratik: kendi maliyet matrisinizi yazın

Kitabın bu bölümünde numaralı alıştırma yok; kitabın ek alıştırmaları O'Reilly sayfasındaki ek materyalde. Aşağıdaki üç görev, bölümün üç sonucunu kendi bağlamınıza taşır.

**Görev 1 — Karar notu (30 dk).** Aklınıza gelen bir ürün fikri için yarım sayfalık not yazın:
- hangi iş metriği iyileşecek ve bugünkü değeri ne;
- hangi model metriği ona bağlanıyor ve neden bu metrik;
- $C_{\text{FN}}$ ve $C_{\text{FP}}$ sayı olarak ne (TL, dakika, kayıp kullanıcı);
- ilk sürüm için eşik ve bu eşiğin doğuracağı işaretleme oranı;
- "ML kullanmasak ne yapardık" alternatifi.

**Beklenen çıktı:** Basit bir kural alternatifi ve sayısal eşik. Eşiksiz not, bitmemiş nottur.

**Görev 2 — Kod üzerinde oynama (15 dk).** Kodu çalıştırın, sonra $C_{\text{FP}}$'yi 50'den 200'e çıkarın. Beklenti: $p^*$ 0.111'den 0.333'e çıkar, işaretlenen oran düşer, doğruluk artar. Sonra taban oranı değiştirin (intercept -4.6 yerine -2.3) ve aynı eşikte maliyetin nasıl patladığını görün.

**Görev 3 — Araştırma/üretim tablosu (20 dk).** Kitabın s. 12-22 karşılaştırmasını okuduktan sonra tabloyu kapatıp kendi cümlelerinizle 6 satır yazın. Sonra açıp karşılaştırın; eksik kalan satır, sizin üretim deneyiminizde en zayıf halkanızdır.

**İpucu.** Maliyet matrisini ürün sahibiyle birlikte doldurun. "Kaçan dolandırıcılık 400 TL" gibi bir sayı, tartışmayı "model iyi mi" sorusundan "hangi hatayı kaç kez yapmayı kabul ediyoruz" sorusuna taşır; doğru tartışma budur.

**Ek okuma.** Kitabın kendi bölüm özeti: https://github.com/chiphuyen/dmls-book/blob/main/summary.md (Bölüm 1 başlığı).

Terraform'un çekirdek döngüsünü sıfırdan: plan, bağımlılık sırası, idempotanlık, kayma, değişmez kaynak.

```python
# PC'de çalıştır — gerekli: yalnızca Python standart kütüphanesi
# Arzu edilen durum + mevcut durum -> plan -> uygula. Terraform'un çekirdek döngüsü.
import copy

IMMUTABLE = {"bucket_adi", "bolge"}          # değişirse kaynak yeniden yaratılır (-/+)

def kaynaklar(ortam):
    """for_each: aynı tanım, üç ortam. Ad çakışması üretimde en sık hata."""
    return {
      f"veri_{ortam}":  {"tip": "bucket", "spec": {"bucket_adi": f"ml-veri-{ortam}", "bolge": "eu-central-1"},
                          "koruma": True},
      f"model_{ortam}": {"tip": "bucket", "spec": {"bucket_adi": f"ml-model-{ortam}", "bolge": "eu-central-1"},
                          "koruma": True},
      f"tablo_{ortam}": {"tip": "tablo", "spec": {"ad": "trip_features", "saklama_gun": 30},
                          "bagimli": [f"veri_{ortam}"]},
      f"egitim_{ortam}": {"tip": "is", "spec": {"komut": "train.py", "gpu": "A10G", "adet": 1},
                          "bagimli": [f"tablo_{ortam}", f"model_{ortam}"]},
      f"uc_{ortam}":    {"tip": "endpoint", "spec": {"model": "v3", "ornek": "g5.xlarge", "adet": 2},
                          "bagimli": [f"model_{ortam}"]},
    }

ARZU = {}
for ortam in ("deneme", "uretim"):            # for_each = ["deneme", "uretim"]
    ARZU.update(kaynaklar(ortam))

def plan(arzu, mevcut):
    adimlar = []
    for ad, r in arzu.items():
        if ad not in mevcut:
            adimlar.append(("ekle", ad))
        elif mevcut[ad]["spec"] != r["spec"]:
            degisen = {k for k in r["spec"] if r["spec"][k] != mevcut[ad]["spec"].get(k)}
            if degisen & IMMUTABLE:
                korumali = r.get("koruma") or mevcut[ad].get("koruma")
                adimlar.append(("degistir(engelli)" if korumali else "degistir", ad))
            else:
                adimlar.append(("guncelle", ad))
    for ad in mevcut:
        if ad not in arzu:
            adimlar.append(("sil(engelli)" if mevcut[ad].get("koruma") else "sil", ad))
    return adimlar

def sirala(arzu):
    kalan, sira, gorulen = list(arzu), [], set()
    while kalan:
        ilerleme = False
        for ad in list(kalan):
            if all(b in gorulen for b in arzu[ad].get("bagimli", [])):
                sira.append(ad); gorulen.add(ad); kalan.remove(ad); ilerleme = True
        if not ilerleme:
            raise ValueError(f"döngüsel bağımlılık: {kalan}")
    return sira

def uygula(arzu, mevcut, adimlar):
    for eylem, ad in adimlar:
        if eylem in ("ekle", "degistir"):
            mevcut[ad] = {"spec": copy.deepcopy(arzu[ad]["spec"]), "koruma": arzu[ad].get("koruma", False),
                          "id": f"{arzu[ad]['tip']}-{abs(hash(ad)) % 10000:04d}"}
        elif eylem == "guncelle":
            mevcut[ad]["spec"] = copy.deepcopy(arzu[ad]["spec"])
        elif eylem == "sil":
            mevcut.pop(ad)
    return mevcut

MEVCUT = {}
p = plan(ARZU, MEVCUT)
print(f"1) ilk plan: {len(p)} kaynak → {dict((e, sum(1 for x in p if x[0]==e)) for e, _ in p)}")
print("   sıra:", sirala(ARZU)[:5], "...")
MEVCUT = uygula(ARZU, MEVCUT, p)
print("2) ikinci plan:", plan(ARZU, MEVCUT) or "boş — idempotent")

MEVCUT["uc_uretim"]["spec"]["adet"] = 6          # elle müdahale: kayma
print("3) kayma sonrası plan:", plan(ARZU, MEVCUT))
MEVCUT = uygula(ARZU, MEVCUT, plan(ARZU, MEVCUT))

ARZU["model_uretim"]["spec"]["bolge"] = "us-east-1"   # değişmez alan
print("4) değişmez alan değişti:", plan(ARZU, MEVCUT),
      "→ korumalı kaynak yeniden yaratılmaz; Terraform planı reddeder")
ARZU["model_uretim"]["spec"]["bolge"] = "eu-central-1"   # koruma yüzünden değişiklik geri alınır

MEVCUT = uygula(ARZU, MEVCUT, plan(ARZU, MEVCUT))

del ARZU["veri_deneme"]; del ARZU["uc_deneme"]     # deneme ortamı kaldırıldı
print("5) kaynak kaldırıldı:", plan(ARZU, MEVCUT), "→ korumalı bucket silinmiyor")
# Beklenen çıktı:
# 1) ilk plan: 10 kaynak → {'ekle': 10}
#    sıra: ['veri_deneme', 'model_deneme', 'tablo_deneme', 'egitim_deneme', 'uc_deneme'] ...
# 2) ikinci plan: boş — idempotent
# 3) kayma sonrası plan: [('guncelle', 'uc_uretim')]
# 4) değişmez alan değişti: [('degistir(engelli)', 'model_uretim')] → korumalı kaynak yeniden yaratılmaz; Terraform planı reddeder
# 5) kaynak kaldırıldı: [('sil(engelli)', 'veri_deneme'), ('sil', 'uc_deneme')] → korumalı bucket silinmiyor
```

Bu 30 satır, Terraform'un bütün karar mekanizması: fark hesabı, topolojik sıra, değişmezlik, koruma. Gerçek araçta üstüne sağlayıcı API'leri, uzak durum ve kilitleme eklenir; mantık aynı kalır.

# Beş aşama, beş çıktı

Projeyi aşamalara bölün; her aşamanın **tek** çıktısı olsun. Aşama çıktısı olmadan sonrakine geçmeyin — cihaz işlerinde geri dönüş pahalıdır çünkü ölçüm ortamı değişir.

## Aşama 1 — Baseline ve bütçe (≈ 60 dk)

[Baseline](term:baseline): modeli eğitin, **doğrulama setiyle** erken durdurun, test setinde tek bir doğruluk sayısı üretin. Aynı anda bütçeyi yazın: boyut (KB), p95 (ms), minimum doğruluk. Bütçe yoksa proje yoktur; "mümkün olduğunca hızlı" bir hedef değildir.

Çıktı: `baseline.json` — parametre, val_acc, test_acc, süre.

## Aşama 2 — Dışa aktarma ve denklik (≈ 90 dk)

`torch.export` ile yakalayın, ONNX'e yazın, ORT'de çalıştırın. 500 örnekte argmax ve fark raporu üretin. Batch 1 ve (destekliyorsa) batch 8 ile deneyin. Core ML varsa `.mlpackage` üretip aynı testi tekrarlayın.

Çıktı: `export_report.json` — opset, girdi/çıktı sözleşmesi, denklik sayıları.

Sık hata: dinamik export'ta `value_info` çelişkisi; çözümü ders 2'de. Batch 1 örneğiyle dinamik eksen tanımlamaya çalışmak `ConstraintViolationError` verir; batch 4 örneği kullanın.

## Aşama 3 — Optimizasyon (≈ 120 dk)

İki varyant üretin: int8 ve (gerekiyorsa) 4-bit. Her biri için boyut, doğruluk, p50. Roofline ile **neden** hızlandığını ya da hızlanmadığını açıklayın. Budama ve damıtma opsiyonel; yaparsanız ince ayarsız/ince ayarlı iki sayı raporlayın.

Çıktı: `variants.json` — tablo + "neden bu varyant" paragrafı.

## Aşama 4 — Ölçüm protokolü (≈ 90 dk)

Isınma (100 çağrı), ölçüm (1000 çağrı), p50/p95/p99, ısıl sapma, bütçe kapısı. Masaüstünde ölçtüyseniz cihaz tahminini **ayrı** bir sütunda verin ve varsayımı yazın (bant genişliği oranı, çekirdek sayısı). Cihazda ölçtüyseniz hangi cihaz, hangi işletim sistemi, hangi güç modu — hepsi raporda.

Çıktı: `bench.json` + bir paragraflık yorum.

## Aşama 5 — Entegrasyon ve model kartı (≈ 180 dk)

Uygulamaya gömün: modeli açılışta yükleyin, ilk çıkarımı arka planda ısıtın, sonucu ana iş parçacığı dışında üretin, hata durumunda (model yüklenemedi) makul bir yedek davranış gösterin. Model kartını yazın: her sayının yanında ölçüm mü tahmin mi olduğu yazılı olsun.

```swift
// iOS — Core ML: model bir kez yüklenir, çıkarım arka planda
final class DigitClassifier {
    private let model: MLModel                // uygulama açılışında bir kez
    private let queue = DispatchQueue(label: "inference", qos: .userInitiated)
    init?() {
        guard let url = Bundle.main.url(forResource: "Tiny", withExtension: "mlmodelc"),
              let ml = try? MLModel(contentsOf: url) else { return nil }
        self.model = ml
    }
    func predict(_ pixels: [Float], completion: @escaping (Int?) -> Void) {   // 64 değer, [0,1]
        guard let input = try? MLMultiArray(shape: [1, 1, 8, 8] as [NSNumber], dataType: .float32) else {
            completion(nil); return
        }
        for i in 0..<64 { input[i] = NSNumber(value: pixels[i]) }
        queue.async {
            guard let out = try? self.model.prediction(
                    from: MLDictionaryFeatureProvider(
                        dictionary: ["img": MLFeatureValue(multiArray: input)])),
                  let logits = out.featureValue(for: "logits")?.multiArrayValue else {
                completion(nil); return
            }
            completion((0..<logits.count).max { logits[$0].floatValue < logits[$1].floatValue })
        }
    }
}
```

Aşama 2'deki dönüşüm tensör girdi/çıktı üretir (`img` → `logits`), sınıf etiketi değil: bu yüzden Vision'ın `VNClassificationObservation` yolu değil, `MLModel.prediction(from:)` + elle argmax kullanılır. Modelin sözleşmesi (isim, şekil, dtype) model kartındakiyle aynı olmak zorunda.

```kotlin
// Android — LiteRT: mmap ile yükle, tek Interpreter, arka planda çalıştır
class DigitClassifier(context: Context) {
    private val interpreter = Interpreter(
        FileUtil.loadMappedFile(context, "tinycnn.tflite"),
        Interpreter.Options().apply { setNumThreads(1) }
    )
    private val input = Array(1) { Array(1) { Array(8) { FloatArray(8) } } }
    private val output = Array(1) { FloatArray(10) }

    fun predict(pixels: FloatArray): Int = synchronized(interpreter) {
        for (r in 0 until 8) for (c in 0 until 8) input[0][0][r][c] = pixels[r * 8 + c]
        interpreter.run(input, output)
        output[0].indices.maxBy { output[0][it] }
    }
}
```

